<div class="welcome-row"><div><div class="form-kicker">OBJETIVOS FINANCEIROS</div><h1>Metas</h1><p class="page-subtitle">Acompanhe aportes, resgates e o progresso dos seus objetivos.</p></div></div>
<?php if($errors): ?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif; ?>
<div class="goal-grid"><?php foreach($goals as $goal): ?><article class="panel goal-card"><div class="goal-card-head"><span class="goal-mark" style="background:<?=e($goal['color'])?>">☆</span><div><strong><?=e($goal['name'])?></strong><small><?=$goal['due_date']?($goal['days_remaining']<0?'Prazo encerrado há '.abs($goal['days_remaining']).' dias':($goal['days_remaining']===0?'Prazo termina hoje':'Faltam '.$goal['days_remaining'].' dias')):'Sem data prevista'?></small></div><span class="status-pill <?=$goal['status']==='active'?'received':($goal['status']==='completed'?'paid':'cancelled')?>"><?=match($goal['status']){'active'=>'Ativa','completed'=>'Concluída',default=>'Cancelada'}?></span></div><p class="goal-description"><?=e($goal['description']?:'Meta financeira pessoal')?></p><div class="goal-progress-row"><strong><?=money((int)$goal['saved'])?></strong><span>de <?=money((int)$goal['target_amount'])?></span></div><div class="budget-progress"><i style="width:<?=$goal['progress']?>%;background:<?=e($goal['color'])?>"></i></div><div class="budget-caption"><span><?=$goal['progress']?>% concluído</span><span>Faltam <?=money((int)$goal['remaining'])?></span></div><div class="goal-linked"><?= $goal['account_name']?'Conta vinculada: '.e($goal['account_name']):'Aportes registrados apenas para acompanhamento' ?></div>
<?php if($goal['status']!=='cancelled'): ?><div class="goal-actions"><form method="get" action="/goals"><input type="hidden" name="history" value="<?=(int)$goal['id']?>"><button>Ver histórico</button></form><a href="/goals?edit=<?=(int)$goal['id']?>#goal-form">Editar</a><?php if($goal['status']==='active'): ?><form method="post" action="/goals/cancel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$goal['id']?>"><button>Cancelar meta</button></form><?php endif; ?></div><?php if($goal['status']==='active'||$goal['status']==='completed'): ?><div class="goal-movement-forms"><form method="post" action="/goals/contribution"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="goal_id" value="<?=(int)$goal['id']?>"><input type="hidden" name="direction" value="contribution"><strong>Novo aporte</strong><input name="amount" inputmode="decimal" placeholder="Valor" required><input type="date" name="movement_date" value="<?=date('Y-m-d')?>" required><?php if($goal['account_id']): ?><select name="account_id" required><option value="">Conta de origem</option><?php foreach($accounts as $account): if((int)$account['id']===(int)$goal['account_id'])continue; ?><option value="<?=(int)$account['id']?>"><?=e($account['name'])?></option><?php endforeach; ?></select><?php endif; ?><button class="button primary">Registrar</button></form><form method="post" action="/goals/contribution"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="goal_id" value="<?=(int)$goal['id']?>"><input type="hidden" name="direction" value="withdrawal"><strong>Resgate</strong><input name="amount" inputmode="decimal" placeholder="Valor" required><input type="date" name="movement_date" value="<?=date('Y-m-d')?>" required><?php if($goal['account_id']): ?><select name="account_id" required><option value="">Conta de destino</option><?php foreach($accounts as $account): if((int)$account['id']===(int)$goal['account_id'])continue; ?><option value="<?=(int)$account['id']?>"><?=e($account['name'])?></option><?php endforeach; ?></select><?php endif; ?><button class="button secondary">Registrar</button></form></div><?php endif; ?><?php endif; ?></article><?php endforeach; ?><?php if(!$goals): ?><div class="empty-account"><span class="empty-icon">☆</span><strong>Defina sua primeira meta</strong><p>Escolha um objetivo, valor e prazo para acompanhar sua evolução.</p></div><?php endif; ?></div>
<?php if($history): ?><section class="panel statement-panel"><div class="panel-head"><div><h3>Histórico de aportes e resgates</h3><p><?=e($history[0]['goal_name'])?></p></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Movimento</th><th>Observações</th><th class="right">Valor</th></tr></thead><tbody><?php foreach($history as $movement): ?><tr><td><?=e(date('d/m/Y',strtotime($movement['movement_date'])))?></td><td><?=$movement['direction']==='contribution'?'Aporte':'Resgate'?></td><td><?=e($movement['notes']?:'—')?><?=$movement['transfer_id']?' · transferência vinculada':''?></td><td class="right <?=$movement['direction']==='contribution'?'amount-in':'amount-out'?>"><?=$movement['direction']==='contribution'?'+':'−'?><?=money((int)$movement['amount'])?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="panel editor-panel" id="goal-form"><div class="panel-head"><div><h3><?=$edit?'Editar meta':'Criar meta financeira'?></h3><p>Opcionalmente vincule uma conta para registrar aportes e resgates como transferências.</p></div></div><form method="post" action="/goals/save" class="data-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Nome da meta<input name="name" maxlength="100" required value="<?=e($edit['name']??'')?>" placeholder="Ex.: Reserva de emergência"></label><label>Valor desejado<input name="target_amount" inputmode="decimal" required value="<?=e(isset($edit['target_amount'])?money_input((int)$edit['target_amount']):'')?>" placeholder="0,00"></label><label>Data de início<input type="date" name="start_date" required value="<?=e($edit['start_date']??date('Y-m-d'))?>"></label><label>Data prevista<input type="date" name="due_date" value="<?=e($edit['due_date']??'')?>"></label><label>Conta vinculada (opcional)<select name="account_id"><option value="">Somente acompanhar</option><?php foreach($accounts as $account): ?><option value="<?=(int)$account['id']?>" <?=($edit['account_id']??'')==$account['id']?'selected':''?>><?=e($account['name'])?></option><?php endforeach; ?></select></label><label>Categoria<select name="category_id" required><option value="">Selecione</option><?php foreach($categories as $category): ?><option value="<?=(int)$category['id']?>" <?=($edit['category_id']??'')==$category['id']?'selected':''?>><?=e($category['name'])?> · <?=$category['type']==='income'?'Receita':'Despesa'?></option><?php endforeach; ?></select></label><label class="span-two">Descrição<input name="description" maxlength="500" value="<?=e($edit['description']??'')?>"></label><label>Cor<input type="color" name="color" value="<?=e($edit['color']??'#168b68')?>"></label><div class="form-actions"><button class="button primary">Salvar meta</button><?php if($edit): ?><a class="button secondary" href="/goals">Cancelar</a><?php endif; ?></div></form></section>
